import re

def classify(text):
    t=text.lower().replace('ё','е')
    laws=[]
    for n,phrase in [('44',r'контрактн\w* систем'),('223',r'закуп\w* отдельными видами юридических лиц')]:
        if re.search(r'(?<!\d)'+n+r'\s*[-‐‑‒–—−]?\s*фз\b|'+phrase,t): laws.append(n+'-ФЗ')
    relevant=bool(laws or re.search(r'госзакуп|госконтракт|муниципальн\w* закуп|контрактн\w* систем|закуп\w* (?:по|для|у единственного|среди|товаров, работ)|\b(?:нмцк|ктру|рнп|еис|смсп|сонко)\b|национальн\w* режим.{0,80}закуп|закуп.{0,80}национальн\w* режим|постановлен\w*.{0,70}\b1875\b|закуп.{0,100}(?:фас|минфин|заказчик|поставщик|контракт)|(?:фас|минфин|заказчик|поставщик|контракт).{0,100}закуп',t))
    if not relevant and not re.search(r'\b(?:закупки|закупок|закупках)\b',t): return None
    if not relevant: return None
    topics=[]
    for label,pattern in [('Нацрежим',r'национальн\w* режим|\b1875\b|стран\w* происхожд'),('ЕИС и электронные процедуры',r'\bеис\b|электронн\w* (?:приемк|площадк|аукцион)'),('РНП и жалобы',r'\bрнп\b|недобросовестн\w* поставщик|жалоб'),('МСП и СОНКО',r'\b(?:смп|смсп|мсп|сонко)\b'),('Контракты и оплата',r'контракт|неустойк|оплат|приемк'),('Требования и заявки',r'заявк|доптребован|нмцк|ктру|обеспечен|гаранти'),('Единственный поставщик',r'единственн\w* поставщик')]:
        if re.search(pattern,t): topics.append(label)
    types=[('Законопроект',r'законопроект|проект\w* (?:закона|постановления|поправок)|(?:первом|втором|третьем) чтении|предложил|общественн\w* обсужден'),('Судебная практика',r'суд[ыаомеб]|кассаци|арбитраж|\bвс рф\b'),('Практика ФАС',r'\b(?:уфас|фас)\b.{0,100}(?:решен|нарушен|жалоб|практик|признал)|практик\w* (?:уфас|фас)'),('Разъяснения',r'разъясн|пояснил|письм|напомнил'),('Изменения НПА',r'поправк|вступ|опубликован|постановлен|утвержден')]
    kind=next((label for label,p in types if re.search(p,t)), 'Новости и обзоры')
    return laws or ['Общие закупочные вопросы'], topics or ['Прочее'], kind
